import hashlib, sys
path='URRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDD'
for variant in ['lower','strip','newline']:
    s=path
    if variant=='lower': s=s.lower()
    if variant=='strip': s=s.strip()
    if variant=='newline': s=s+'\n'
    print(variant, hashlib.md5(s.encode()).hexdigest())

